// packet §3: external-untrusted envelope BEFORE any model classification.
// Metadata path first (05_ §2 minimisation): forward identifiers and
// timings; carry transcript text only in `restricted_content`, which the
// wrapper decides whether to expose to a model.
return items.map(i => ({ json: {
  envelope: { trust: 'external-untrusted', partition: 'business',
              source: 'callrail', received_at: new Date().toISOString() },
  metadata: { call_id: i.json.call_id, from: i.json.from_masked,
              duration_s: i.json.duration, started_at: i.json.started_at },
  restricted_content: { transcript: i.json.transcript ?? null },
  content_forwarded: Boolean(i.json.transcript)  // B-2 evidence: logged
} }));
